# prompts.py - picture prompts for roswell-balloon (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, NO references)
# STYLE / CHARACTER / KEY / BG blocks word for word from memory/STYLE.md (the channel's locked look).
# RANCHER = the hero's role block; after measuring the hero it becomes RANCHER2 with the measured hat colours.
import json, sys
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
RANCHER = " This character is a rancher: exactly the same simple white character, wearing only a brown cowboy hat (a dented crown and a wide brim curled up at both sides, flat #A86B3C with a darker #7A4A26 hat band and shade) sitting on top of the round head - nothing else added, no hair, no clothes."
RANCHER2 = RANCHER  # replaced after the hero is measured (see below)
OFFICER = " This character is an army officer of the 1940s: exactly the same simple white character, wearing only an olive-drab military peaked cap with a dark brown visor and a small gold badge on the front (flat olive #6F7347 crown with a darker #565A36 shade, dark brown #3B2A1E visor, gold #E5B93A badge) sitting on top of the round head - nothing else added, no hair, no clothes."
FAN = " This character wears only a pointy cone-shaped hat folded from crinkled shiny silver kitchen foil (flat light grey #C9CDD2 with white #F2F4F6 highlights and darker #9AA0A7 creases) sitting on top of the round head - nothing else added, no hair, no clothes."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no letters, no numbers, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
ROW3 = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
def tail(role, key='green'): return " Whole bodies in frame with a margin. " + CHAR + role + " " + KEY(key)
if len(sys.argv) > 1: RANCHER2 = open(sys.argv[1]).read().strip()

P = {
 'hero': ("2:3", "Full body, three-quarter view facing to the right, puzzled: the hand on the RIGHT side of the image holds up a crumpled piece of shiny silver foil (flat light grey #C9CDD2 with white highlights) at head height and he looks at it, the other hand scratches the side of the head just below the hat brim, one eyebrow raised higher than the other, a small wavy closed mouth. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + RANCHER + " " + KEY()),
 'rancher3': ("3:2", ROW3 + "LEFT copy: three-quarter view facing to the RIGHT, looking up at the sky to the upper right, one flat hand held at the hat brim shading the eyes, the other arm down, eyebrows raised, a small round open mouth. MIDDLE copy: facing the viewer, amazed: holding a big completely blank plain white newspaper sheet open in front of the belly with both hands (no writing, no pictures on it, the face fully visible above it), eyes wide, eyebrows raised high, mouth wide open in a big smile with the pink tongue showing. RIGHT copy: facing the viewer, disappointed: a big shrug with both palms turned up and held out to the sides, half-closed unimpressed eyes, flat eyebrows, a flat straight mouth." + tail(RANCHER2)),
 'officer3': ("3:2", ROW3 + "LEFT copy: three-quarter view facing to the RIGHT, proudly announcing: holding a big grey cone-shaped megaphone to the mouth with one hand, the other arm raised high with a fist, eyebrows raised, eyes wide and excited. MIDDLE copy: facing the viewer, nervous: one hand raised beside the head holding up a short wooden stick with a completely blank plain white rectangular sign board on top (wider than the head, no writing on it), the other hand scratching the back of the head, a big forced toothy smile, eyebrows tilted up in the middle, eyes wide. RIGHT copy: three-quarter view facing to the LEFT, secretive: one finger pressed on the closed lips in a 'shh' gesture, the other hand on the hip, sly half-closed eyes looking sideways at the viewer, one eyebrow lowered." + tail(OFFICER)),
 'fan3': ("3:2", ROW3 + "LEFT copy: three-quarter view facing to the RIGHT, excited: one arm stretched straight out pointing to the right at head height, eyes wide and wild, eyebrows raised high, mouth wide open shouting with the pink tongue showing. MIDDLE copy: facing the viewer, both arms thrown up high and wide, eyes wide, eyebrows raised high, a huge open-mouth smile with the pink tongue showing. RIGHT copy: three-quarter view facing to the LEFT, shocked: leaning back a little with both open hands raised beside the face, eyes huge, eyebrows raised very high, jaw dropped with the mouth wide open." + tail(FAN)),
 'objects': ("3:2", "Three separate objects side by side in one row with wide empty gaps between them, drawn at the same scale. LEFT: a cartoon radar reflector kite: a box-kite shape made of shiny silver foil panels (flat #C9CDD2 with white #F2F4F6 highlights and a #8E959D shade) stretched over thin light-tan balsa-wood sticks (#E2C38E), a few sticks wrapped with strips of white tape printed with tiny pink flowers (#F28DB5); about as tall as it is wide. MIDDLE: a messy flat heap of crash debris: crumpled sheets of shiny silver foil, broken thin light-tan sticks, a few torn grey-brown rubber strips (#6E5F55) and one loose strip of white tape with tiny pink flowers; much wider than tall, with a flat bottom. RIGHT: a classic 1950s flying saucer seen from the side: a wide shiny silver disc (#C9CDD2 with white highlights and a #8E959D shade) with a small clear pale-blue glass dome on top (#BFE6F7) and a row of small round yellow lights (#F7D046) along the rim, nobody inside. " + OBJ + " " + KEY()),
 'ranch': ("2:3", "A wide dry New Mexico ranch on a sunny summer day, side view at ground level, vertical picture. The top 55 % is a clear light-blue sky (#8ED3F5 at the top to #CFEFFC near the horizon) with one small simple white cloud. The horizon is a flat line at 55 % of the height, with low flat-topped red-brown mesas (#B9653D with a darker #93492A shade) far away on the left and on the right. Below the horizon flat sandy desert ground (#E3C38A with a lighter #EED39F band near the horizon) with a few small round grey-green sage bushes (#8FA27A) and small pebbles; on the RIGHT side in the middle distance a simple wooden windmill water pump on a tall thin lattice tower next to a short wooden fence. Open flat empty ground in the lower middle. No people, no animals, no buildings, no text. " + BG),
 'base': ("2:3", "A 1940s army airfield on a sunny day, side view at ground level, vertical picture. The top 55 % is a clear light-blue sky (#8ED3F5 at the top to #CFEFFC near the horizon). In the middle distance, slightly LEFT of centre, a big curved-roof aircraft hangar (a half-cylinder shape, flat pale grey-green metal #A9B2A0 with a darker #879080 shade, a few vertical seam lines, big closed sliding doors) standing on the horizon at 55 % of the height; on the RIGHT a tall thin white flagpole with a small American flag. In front, flat light-grey concrete ground (#C2BFB8 with a darker #A9A69F band far away) with one straight yellow painted line. Open flat empty ground in the lower middle. No people, no planes, no vehicles, no text. " + BG),
 'sky': ("2:3", "High up in the sky above the clouds, vertical picture. The top 62 % is a deep clear blue sky (#2E6FC4 at the top to #86C6F0 near the cloud line). The bottom 38 % is a flat sea of big soft white puffy cloud tops (#FFFFFF with pale blue-grey #D6E6F2 shading) with a gently rounded cloud horizon at 62 % of the height. No sun, no birds, no planes, no ground, no text. " + BG),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# roswell-balloon - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
for k, (ar, p) in P.items(): print(k, ar, len(p))
